import { OrdersController } from './orders.controller';

describe('OrdersController', () => {
    it('returns the order the service resolves', async () => {
        const orders = { findOne: jest.fn().mockResolvedValue({ id: 'o1' }) };
        const controller = new OrdersController(orders as any);

        await expect(controller.findOne('o1')).resolves.toEqual({ id: 'o1' });
        expect(orders.findOne).toHaveBeenCalledWith('o1');
    });
});

